import {escapeHTML as h,safeURL,money,amountText,supportReference,paymentRatio,filterSupport,filterPoliticians,filterElections,electionCandidates,candidatePromises,normalizeName,readPreferences} from './core.mjs';

const app=document.getElementById('app');
let preferences=readPreferences(localStorage);
let catalog;
let loadingToken=0;
let toastTimer;
const pageSize=24;
const themeNames={all:'すべて',economy:'税・暮らし',education:'子育て・教育',childcare:'子育て・教育',child:'子育て',social:'社会保障',labor:'雇用・労働',welfare:'医療・福祉',reform:'政治改革',foreign:'外交',security:'外交・安全保障',disaster:'防災',energy:'エネルギー',agriculture:'農業・食料',other:'その他'};
const navItems=[['/','home','ホーム'],['/politicians','people','議員を探す'],['/elections','vote','選挙・候補者'],['/promises','check','公約を確かめる'],['/funding','bank','支援のお金'],['/following','bookmark','フォロー中'],['/sources','book','出典・更新履歴']];
const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',people:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',vote:'<path d="m9 11 3 3 8-8M5 7H3v14h18V11M3 17h18M7 7V3h10v3"/>',check:'<path d="M9 3H5v18h14V3h-4M9 2h6v4H9zM8 13l2 2 5-5"/>',bank:'<path d="m3 8 9-5 9 5ZM4 21h16M6 11v7M10 11v7M14 11v7M18 11v7"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4Z"/>',book:'<path d="M12 5v16M12 5C8 2 3 3 3 3v15s5-1 9 3c4-4 9-3 9-3V3s-5-1-9 2Z"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',external:'<path d="M14 3h7v7m-1-6-9 9M10 3H3v18h18v-7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',window:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 8h18M9 8v13"/>',speech:'<path d="M21 15V3H3v18l5-6Z"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a18 18 0 0 1 0 18 18 18 0 0 1 0-18"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.info}</svg>`;}
function route(){const raw=location.hash.replace(/^#/,'')||'/';const url=new URL(raw,location.origin);return {path:url.pathname.replace(/\/$/,'')||'/',params:url.searchParams};}
function link(path,label,classes='inline-link',glyph='arrow'){return `<a class="${classes}" href="#${h(path)}">${h(label)}${glyph?icon(glyph):''}</a>`;}
function routeURL(path,params){const query=new URLSearchParams(params);for(const [key,value] of [...query])if(!value||value==='all')query.delete(key);return path+(query.size?'?'+query:'');}
function unique(values){return [...new Set(values.filter(Boolean))];}
function personByID(id){return catalog.politicians.find(person=>person.id===id);}
function candidateByID(id){return catalog.candidates.find(candidate=>candidate.id===id);}
function sourceByID(id){return catalog.sources.find(source=>source.id===id);}
function sourceRef(ids,additional=''){const sources=unique(ids||[]).map(sourceByID).filter(Boolean);if(!sources.length)return '';return `<div class="source-strip">${sources.slice(0,3).map(source=>link('/source/'+encodeURIComponent(source.id),source.publisher||'根拠資料','','')).join('')}${additional?`<span>${h(additional)}</span>`:''}</div>`;}
function partyTone(name){if(!name)return 'unknown';if(name==='無所属')return 'tone-7';const explicit={'自由民主党':'ldp','国民民主党':1,'日本維新の会':5,'立憲民主党':2,'中道改革連合':2,'日本共産党':4,'参政党':6,'れいわ新選組':3,'あおば市民党':0,'ひだまり未来党':1};if(explicit[name]!==undefined)return 'tone-'+explicit[name];let sum=0;for(const char of name)sum=(sum*31+char.codePointAt(0))>>>0;return 'tone-'+sum%8;}
function party(name,prefix=''){return `<span class="party ${partyTone(name)}">${prefix?h(prefix)+' ':''}${h(name||'所属党は未確認')}</span>`;}
function tag(text,type=''){return `<span class="tag ${type}">${h(text)}</span>`;}
function notice(text,type=''){return `<div class="notice ${type}">${icon('info')}<span>${h(text)}</span></div>`;}
function empty(title,body,action=''){return `<div class="empty"><h3>${h(title)}</h3><p>${h(body)}</p>${action}</div>`;}
function heading(title,eyebrow='',lead=''){return `<header class="page-heading">${eyebrow?`<span class="eyebrow">${h(eyebrow)}</span>`:''}<h1>${h(title)}</h1>${lead?`<p class="lead">${h(lead)}</p>`:''}</header>`;}
function save(){try{localStorage.setItem('politics-window-v1',JSON.stringify(preferences));}catch{toast('このブラウザーでは保存できません。現在の画面では操作できます。');}}
function toast(text){const node=document.getElementById('toast');node.textContent=text;node.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('visible'),3500);}
function isActive(path,current){return path==='/'?current==='/':current.startsWith(path)||path==='/elections'&&(current.startsWith('/election/')||current.startsWith('/compare/'))||path==='/politicians'&&current.startsWith('/politician/');}
function followButton(person){const followed=preferences.followed.includes(person.id);return `<button class="button ${followed?'primary':''}" type="button" data-action="follow" data-id="${h(person.id)}" aria-pressed="${followed}">${icon('bookmark')}${followed?'フォロー中':'フォローする'}</button>`;}
function identity(person,{election=false,small=false}={}){const affiliation=election?person.partyAtElection:person.currentParty;return `<div class="identity"><span class="avatar" aria-hidden="true">${h(person.name.replace(/\s/g,'').slice(0,1))}</span><div class="identity-copy">${person.kana?`<small>${h(person.kana)}</small>`:''}<h3>${h(person.name)}</h3><div class="identity-tags">${party(affiliation)}${person.house?tag(person.house):''}${election?tag(person.incumbencyAtElection||'職歴区分は未確認','neutral'):''}</div></div></div>`;}
function personCard(person){return `<article class="card person-card">${identity(person)}<div class="person-meta"><span>${h(person.district||'選挙区は未確認')}${person.electionsCount!==null&&person.electionsCount!==undefined?' · 当選'+h(person.electionsCount)+'回':''}</span><span class="caucus">会派：${h(person.caucus||'未確認')}</span><span>名簿の基準日：${h(person.currentAsOf||'未確認')}</span>${person.currentParty?`<span>党所属の確認日：${h(person.partyObservedAt||person.currentPartyAsOf||catalog.meta.checkedAt)}</span>`:''}</div><div class="card-footer">${link('/politician/'+person.id,'公約・実績を見る')}${followButton(person)}</div></article>`;}
function promiseCard(promise,{compact=false}={}){
 const candidate=candidateByID(promise.candidateId),person=personByID(promise.politicianId),partyOwned=promise.ownerType==='party';
 return '<article class="card promise-card">'+
  '<div class="tag-row">'+tag(themeNames[promise.theme]||promise.theme||'公約')+tag(promise.progress||'未評価',promise.progressStage==='partially-implemented'?'amber':'neutral')+'</div>'+
  (partyOwned?party(promise.partyName):candidate?party(candidate.partyAtElection):'')+
  '<p class="promise-label">'+h(partyOwned?'党の公約 · 第'+promise.applicableElectionNumber+'回衆院選':(candidate?.name||person?.name||'候補者本人')+' · '+(catalog.elections.find(e=>e.id===promise.electionId)?.district||'本人の公約'))+' · '+h(promise.asOf||'時点は未確認')+'</p>'+
  '<h3>'+h(promise.title||promise.summary)+'</h3>'+
  (promise.summary&&promise.summary!==promise.title?'<p class="promise-summary">'+h(promise.summary)+'</p>':'')+
  '<div class="promise-state"><span class="quiet">確認できた状況'+(promise.progressAsOf?' · '+h(promise.progressAsOf)+'時点':'')+'</span><p>'+h(promise.progressReason||'実施状況を判断する根拠は未収録です。')+'</p>'+
  (promise.effectiveAt?'<p class="quiet">'+(promise.implementationStarted?'対応部分の開始日':'施行・開始予定日')+'：'+h(promise.effectiveAt)+'</p>':'')+
  (promise.progressScope?'<p class="secondary">'+h(promise.progressScope)+'</p>':'')+
  (promise.notes?'<p class="secondary">'+h(promise.notes)+'</p>':'')+'</div>'+
  sourceRef(promise.sourceIds,promise.gazettePage?'選挙公報 '+promise.gazettePage+'ページ':'公約原文')+
  (promise.progressEvidenceVerified?sourceRef(promise.progressSourceIds,'本人の行動・制度の状況を確認した資料'):'')+
  link('/promise/'+promise.id,compact?'原文・進捗の根拠を見る':'公約と根拠を見る')+'</article>';
}
function activityHTML(activity){return `<div class="fact"><span class="fact-icon">${icon('speech')}</span><div><span class="quiet">${h(activity.date||'日付未確認')} · ${h(activity.type||'活動記録')}</span><h3>${h(activity.title)}</h3><p>${h(activity.summary||'')}</p><small>本人の関わり：${h(activity.role||'未確認')}</small>${activity.relationToElectionPromise?`<small>${h(activity.relationToElectionPromise)}</small>`:''}${sourceRef(activity.sourceIds)}</div></div>`;}
function amountHTML(record,key,label){const value=record[key];const raw=amountText(record,key);const unknown=value===null||value===undefined;const split=raw.indexOf('（');const text=unknown?'未確認':split>=0?raw.slice(0,split):raw;const note=split>=0?raw.slice(split):'';return `<div><span class="amount-label">${h(label)}</span><strong class="amount-value ${unknown?'unknown':text.length>12?'long':''}">${h(text)}</strong>${note?`<span class="amount-note">${h(note)}</span>`:''}</div>`;}
function fundingCard(record){const reference=supportReference(record);return `<article class="card funding-card"><div class="tag-row">${tag(record.region==='domestic'?'国内':'海外')}${tag(record.supportType,'neutral')}${tag(record.repayment,'neutral')}</div><h3>${h(record.shortTitle||record.title)}</h3><p class="recipient">支援先：${h(record.country||record.recipient)}</p><div class="amount-grid">${amountHTML(record,reference.kind==='budget'?'budgetAmountJPY':'announcedAmountJPY',reference.label)}${amountHTML(record,'paidAmountJPY',record.paymentLabel||'確認できた支払・実行額')}</div>${reference.kind==='budget'?`<p class="quiet">発表総額：未確認。左の数字は予算額です。</p>`:''}<p class="period">${h(record.paidPeriod||record.announcedPeriod||'対象期間は未確認')}</p>${record.paidAmountIsDerived?tag('公開数値からの計算値','amber'):''}${record.paidAmountIsApproximate?tag('原資料の概数','neutral'):''}<p class="funding-scope">${h(record.paidScope||'支払いの範囲は未確認です。')}</p><div class="card-footer">${tag(record.status||'確認中',record.paidAmountJPY===null?'neutral':'')}${link('/funding/'+record.id,'支払いの詳細を見る')}</div></article>`;}
function homePage(){const followed=catalog.politicians.filter(person=>preferences.followed.includes(person.id));const activities=[...catalog.activities].sort((a,b)=>(b.date||'').localeCompare(a.date||''));return `<section class="home-hero"><span class="eyebrow">知ることから、はじめよう。</span><h1>約束の、その先へ。</h1><p class="lead">何を約束し、何をした？ お金はどこへ？<br>気になる政治を、事実から確かめる。</p><form class="search-form" data-form="home-search"><label class="offscreen" for="home-q">議員・選挙区で探す</label><input id="home-q" name="q" type="search" placeholder="議員の名前・選挙区で探す"><button class="button primary" type="submit">${icon('search')}探す</button></form></section><div class="quick-grid">${link('/politicians','議員を探す','quick-link','people')}${link('/elections','候補者を比べる','quick-link','vote')}${link('/funding','お金の行き先','quick-link','bank')}</div><div class="coverage-line"><span>議員名簿 <strong>${catalog.politicians.length.toLocaleString('ja-JP')}</strong>人</span><span>候補者 <strong>${catalog.candidates.length}</strong>人</span><span>支援 <strong>${catalog.support.length}</strong>件</span></div><div class="home-coverage">${notice(catalog.meta.scopeNote||'掲載できた資料から順に収録しています。全ての選挙・支援を網羅しているわけではありません。')}${link('/methodology','掲載範囲と確認のルールを見る')}</div><div class="section-heading"><h2>フォロー中の議員</h2>${link('/following','一覧を見る')}</div>${followed.length?`<div class="cards">${followed.slice(0,2).map(personCard).join('')}</div>`:empty('気になる議員を登録できます','議員の詳細画面で「フォローする」を押すと、ここに表示されます。',link('/politicians','議員を探す','button'))}<div class="section-heading"><h2>公約の進捗を確かめる</h2>${link("/promises?status=verified","根拠を確認した記録を見る")}</div>${notice("本人の行動、法案提出、制度の成立と実施開始を分けて確認しています。")}<div class="section-heading"><h2>確認できた議会活動</h2><span>日付の新しい順</span></div>${activities.length?`<div class="facts-list">${activities.slice(0,2).map(activityHTML).join('')}</div>`:empty('活動記録は確認中です','資料の確認ができた記録から掲載します。')}<div class="section-heading"><h2>支援のお金</h2>${link('/funding','すべて見る')}</div><div class="cards">${catalog.support.slice(0,2).map(fundingCard).join('')}</div>`;}
function politiciansPage(params,following=false){const query=params.get('q')||'';const house=params.get('house')||'all';const partyFilter=params.get('party')||'all';const people=filterPoliticians(catalog.politicians,{query,house,party:partyFilter,followedOnly:following,followed:preferences.followed});const maxPage=Math.max(1,Math.ceil(people.length/pageSize));const page=Math.max(1,Math.min(maxPage,Number(params.get('page'))||1));const parties=unique(catalog.politicians.map(person=>person.currentParty)).sort((a,b)=>a.localeCompare(b,'ja'));const path=following?'/following':'/politicians';return `${heading(following?'フォロー中の議員':'議員を探す',following?'このブラウザーで保存':'国会の公式名簿から','所属政党は党の資料で確認できた場合に表示します。会派は別の項目です。')}<form class="filters" data-form="people-filter" data-path="${path}"><label class="filter-field filter-search">名前・選挙区・政党・会派<input type="search" name="q" value="${h(query)}" placeholder="例：岸田、広島、自由民主党"></label><label class="filter-field">議会<select name="house"><option value="all">衆議院・参議院</option>${['衆議院','参議院'].map(value=>`<option ${house===value?'selected':''}>${h(value)}</option>`).join('')}</select></label><label class="filter-field">確認できた所属政党<select name="party"><option value="all">すべて</option>${parties.map(value=>`<option ${partyFilter===value?'selected':''}>${h(value)}</option>`).join('')}</select></label><button class="button primary" type="submit">絞り込む</button></form><div class="section-heading"><h2>${people.length.toLocaleString('ja-JP')}人</h2><span>基準日：衆 ${h(catalog.meta.houseAsOf||'未確認')}／参 ${h(catalog.meta.councilAsOf||'未確認')}</span></div>${people.length?`<div class="cards person-list">${people.slice((page-1)*pageSize,page*pageSize).map(personCard).join('')}</div><div class="pagination">${page>1?link(routeURL(path,{q:query,house,party:partyFilter,page:page-1}),'前へ','button compact','back'):'<span></span>'}<span>${page} / ${maxPage}ページ</span>${page<maxPage?link(routeURL(path,{q:query,house,party:partyFilter,page:page+1}),'次へ','button compact'):''}</div>`:empty(following?'該当するフォローはありません':'該当する議員は見つかりませんでした','検索条件を変えるか、議員の詳細画面からフォローしてください。',link('/politicians','議員一覧へ','button'))}`;}
function politicianPage(id){const person=personByID(id);if(!person)return missing('議員');const promises=catalog.promises.filter(item=>item.politicianId===id);const activities=catalog.activities.filter(item=>item.politicianId===id);const support=catalog.support.filter(item=>(item.politicianRoles||[]).some(role=>role.politicianId===id||normalizeName(role.name)===normalizeName(person.name)));const candidate=catalog.candidates.find(item=>item.politicianId===id);const partyPromises=candidate?candidatePromises(catalog,candidate).party:[];return `${link('/politicians','議員一覧に戻る','back','back')}<div class="profile-header"><span class="avatar" aria-hidden="true">${h(person.name.replace(/\s/g,'').slice(0,1))}</span><div><span class="eyebrow">${h(person.house)} · ${person.electionsCount!==null&&person.electionsCount!==undefined?'当選'+h(person.electionsCount)+'回':'当選回数は未確認'}</span><h1>${h(person.name)}</h1><div class="identity-tags">${party(person.currentParty)}${tag('現職','neutral')}</div><p class="quiet">${h(person.district)}<br>会派：${h(person.caucus||'未確認')}<br>名簿の基準日：${h(person.currentAsOf||'未確認')}</p></div></div><div class="page-actions">${followButton(person)}${candidate?link('/election/'+candidate.electionId,'選挙の候補者を見る','button','vote'):''}${safeURL(person.profileUrl)?`<a class="button" href="${h(safeURL(person.profileUrl))}" target="_blank" rel="noopener noreferrer">公式プロフィール ${icon('external')}</a>`:''}</div>${sourceRef(person.sourceIds,person.currentParty?`所属党の確認日：${person.partyObservedAt||person.currentPartyAsOf||catalog.meta.checkedAt}`:'所属政党は未確認です。会派からは推測していません。')}<nav class="profile-subnav" aria-label="議員情報の項目"><a href="#/politician/${h(id)}?section=activities">実績・公約</a><a href="#/politician/${h(id)}?section=funding">関わった支援</a><a href="#/politician/${h(id)}?section=career">経歴</a></nav><div class="section-heading" id="activities"><h2>これまでに、何をした？</h2></div>${activities.length?activities.map(activityHTML).join(''):empty('活動記録は未収録です','活動がなかったという意味ではありません。会議録・提出法案などの確認が必要です。')}<div class="section-heading"><h2>選挙の公約と、その後</h2></div>${promises.length?`<div class="stack">${promises.map(item=>promiseCard(item,{compact:true})).join('')}</div>`:empty('この議員の公約は確認中です','選挙時の原文と本人の行動を照合してから掲載します。')}${partyPromises.length?`<div class="section-heading"><h2>立候補時の所属党の公約</h2></div>${notice("党の公約と制度の進捗です。この議員個人の約束や成果とは区別します。")}<div class="stack">${partyPromises.map(item=>promiseCard(item,{compact:true})).join("")}</div>`:""}<div class="section-heading" id="funding"><h2>関与を確認できた支援</h2></div>${support.length?`<div class="stack">${support.map(fundingCard).join('')}</div>`:empty('この議員との関係は未収録です','政府の支援を、そのまま議員個人の支出や寄付として扱いません。')}<div class="section-heading" id="career"><h2>経歴・本人の公表情報</h2></div><div class="card">${(person.career||[]).map(item=>`<div class="fact"><div><h3>${h(item.title)}</h3><p class="quiet">${h(item.kind||'過去の役職')}</p>${sourceRef(item.sourceIds)}</div></div>`).join('')}${person.careerSummary?`<p>${h(person.careerSummary)}</p>`:`<p>詳細な職歴は、公式プロフィールの原文をご確認ください。</p>`}${safeURL(person.profileUrl)?`<a class="inline-link" href="${h(safeURL(person.profileUrl))}" target="_blank" rel="noopener noreferrer">公式プロフィールを開く ${icon('external')}</a>`:''}${person.naturalizationDisclosure?.selfPublished===true?`<div class="promise-state"><p>${h(person.naturalizationDisclosure.text)}</p>${sourceRef(person.naturalizationDisclosure.sourceIds)}</div>`:''}<p class="quiet">所属政党の履歴や本人公表の経歴は、根拠が確認できたものだけを掲載します。</p></div>`;}
function electionPageList(params){
 const query=params.get('q')||'',prefecture=params.get('prefecture')||'all',type=params.get('type')||'all';
 const elections=filterElections(catalog.elections,catalog.candidates,{query,prefecture,type,proportionalCandidacies:catalog.proportionalCandidacies||[]});
 const maxPage=Math.max(1,Math.ceil(elections.length/pageSize)),page=Math.max(1,Math.min(maxPage,Math.floor(Number(params.get('page'))||1)));
 const prefectures=unique(catalog.elections.flatMap(e=>[e.prefecture,...(e.prefectures||[])]));
 const listedPeople=new Set(elections.flatMap(e=>electionCandidates(catalog,e.id).map(c=>c.id)));
 return `${heading('選挙と候補者','選挙ごとの情報を保存','小選挙区・比例代表を選び、候補者名や立候補時の党派で探せます。重複立候補は同じ人物として扱います。')}
 <div class="pills" role="group" aria-label="選挙の種類">${[['all','すべて'],['constituency','小選挙区'],['proportional','比例代表']].map(([value,label])=>`<a class="pill election-type" href="#${h(routeURL('/elections',{q:query,prefecture,type:value}))}" ${type===value?'aria-current="page"':''}>${label} ${catalog.elections.filter(e=>value==='all'||(e.electionType||'constituency')===value).length}</a>`).join('')}</div>
 <form class="filters" data-form="elections-filter"><input type="hidden" name="type" value="${h(type)}"><label class="filter-field filter-search">選挙区・候補者名・党派<input type="search" name="q" value="${h(query)}" placeholder="例：東京、候補者名、自由民主党"></label><label class="filter-field">都道府県<select name="prefecture"><option value="all">全国</option>${prefectures.map(value=>`<option ${prefecture===value?'selected':''}>${h(value)}</option>`).join('')}</select></label><button class="button primary" type="submit">絞り込む</button></form>
 <div class="section-heading"><h2>${elections.length}選挙区・ブロック</h2><span>掲載候補者 ${listedPeople.size.toLocaleString('ja-JP')}人（重複を除く）</span></div>
 <div class="stack">${elections.slice((page-1)*pageSize,page*pageSize).map(election=>`<article class="card election-card"><div class="tag-row">${tag(election.status||'状態は未確認','neutral')}${tag(election.electionType==='proportional'?'比例代表':election.prefecture||election.chamber||'小選挙区')}</div><h2>${h(election.name)}</h2><p class="lead">投票日：${h(election.electionDate||'未確認')}</p><p class="quiet">${h(election.electionType==='proportional'?'総務省の公式名簿に掲載された全候補者。小選挙区との重複立候補を含みます。':election.coverage||'掲載範囲は確認中です。')}</p><div class="card-footer"><span class="quiet">${electionCandidates(catalog,election.id).length}人の候補者</span>${link('/election/'+election.id,'候補者を見る','button primary')}</div>${sourceRef(election.sourceIds)}</article>`).join('')||empty('該当する選挙区・ブロックはありません','検索条件を変えてください。')}</div>
 <div class="pagination">${page>1?link(routeURL('/elections',{q:query,prefecture,type,page:page-1}),'前へ','button compact','back'):''}<span>${page} / ${maxPage}ページ</span>${page<maxPage?link(routeURL('/elections',{q:query,prefecture,type,page:page+1}),'次へ','button compact'):''}</div>
 ${notice(catalog.meta.isDemo?'架空の操作サンプルです。':`第51回衆院選の小選挙区${catalog.elections.filter(e=>e.electionType!=='proportional').length}区${catalog.proportionalCandidacies?.length?'と比例11ブロックの名簿':''}を収録。参議院選・地方選は未収録です。本人の公約本文の収録範囲は、候補者名簿の範囲とは異なります。`)}`;
}

function selections(electionID){const all=electionCandidates(catalog,electionID);const ids=preferences.compare[electionID]||[];return all.filter(candidate=>ids.includes(candidate.id));}

function electionPage(id,params=new URLSearchParams()){
 const election=catalog.elections.find(item=>item.id===id);if(!election)return missing('選挙');
 const all=electionCandidates(catalog,id),selected=selections(id),isPR=election.electionType==='proportional';
 const query=params.get('q')||'',partyFilter=params.get('party')||'all',search=normalizeName(query).toLocaleLowerCase('ja');
 const candidates=all.filter(candidate=>(partyFilter==='all'||candidate.partyAtElection===partyFilter)&&(!search||normalizeName(candidate.name+' '+(candidate.kana||'')+' '+(candidate.listedName||'')).toLocaleLowerCase('ja').includes(search)));
 const maxPage=Math.max(1,Math.ceil(candidates.length/pageSize)),page=Math.max(1,Math.min(maxPage,Math.floor(Number(params.get('page'))||1)));
 const gazettes=unique([election.gazetteUrl,...(election.gazetteUrls||[])]).filter(safeURL);
 return `${link('/elections'+(isPR?'?type=proportional':''),'選挙の一覧に戻る','back','back')}${heading(election.district||election.name,election.name,`投票日：${election.electionDate||'未確認'} · ${election.status||'状態は未確認'}`)}
 ${notice(isPR?'比例の名簿順位と、小選挙区との重複立候補を表示しています。同順位は当選順ではありません。本人の公約と党の公約、現在所属を区別して確認できます。':'所属・公約は立候補当時の情報です。党の公約は本人の公約と区別します。公報に書かれた経歴は本人の申告として表示します。現在所属は議員の詳細で確認できます。')}
 ${gazettes.length?`<div class="page-actions">${gazettes.map((url,i)=>`<a class="button" href="${h(safeURL(url))}" target="_blank" rel="noopener noreferrer">選挙公報の原文${gazettes.length>1?' '+(i+1):''} ${icon('external')}</a>`).join('')}</div><p class="quiet">公報へのリンクを確認。本文の要約は確認できた分から掲載しています。</p>`:''}
 <div class="selection-summary" aria-live="polite"><strong>${selected.length}人を選択中</strong><p>${h(selected.map(candidate=>candidate.name).join(' ／ ')||'比べたい候補者を２〜３人選んでください。')}</p>${selected.length>=2?link('/compare/'+id,`選んだ${selected.length}人を比較する`,'button primary full'):'<button class="button primary full" disabled>２人以上を選んでください</button>'}</div>
 ${isPR?`<form class="filters" data-form="candidate-filter" data-election="${h(id)}"><label class="filter-field filter-search">候補者の名前<input type="search" name="q" value="${h(query)}"></label><label class="filter-field">立候補時の党派<select name="party"><option value="all">すべて</option>${unique(all.map(c=>c.partyAtElection)).map(value=>`<option ${value===partyFilter?'selected':''}>${h(value)}</option>`).join('')}</select></label><button class="button primary" type="submit">絞り込む</button></form>`:''}
 <div class="section-heading"><h2>候補者 ${candidates.length}人${isPR?` ／ 名簿全${all.length}人`:''}</h2><span>公式資料の掲載順</span></div>
 <div class="stack">${candidates.slice((page-1)*pageSize,page*pageSize).map(candidate=>{
  const promises=candidatePromises(catalog,candidate),activities=catalog.activities.filter(item=>item.candidateId===candidate.id||candidate.politicianId&&item.politicianId===candidate.politicianId);
  const originalElection=catalog.elections.find(e=>e.id===candidate.originalElectionId);
  return `<article class="card candidate-card">${identity(candidate,{election:true})}
  ${isPR?`<div class="tag-row candidacy-tags">${tag(candidate.listRank?'名簿順位 '+candidate.listRank+'位':'名簿順位は未確認','neutral')}${candidate.rankTied?tag('同順位','neutral'):''}${tag(candidate.dualCandidacy===true?'小選挙区と重複立候補':candidate.dualCandidacy===false?'比例単独':'重複区分は未確認','neutral')}</div>${candidate.dualCandidacy&&originalElection?`<p class="quiet">小選挙区：${h(originalElection.district)} ${link('/election/'+originalElection.id,'同じ候補者を見る')}</p>`:''}`:''}
  ${isPR&&candidate.listedName&&normalizeName(candidate.listedName)!==normalizeName(candidate.name)?`<p class="quiet">比例名簿の表記：${h(candidate.listedName)}</p>`:''}${candidate.selfDeclaredOrganization?`<p class="person-meta">公報に記載された団体：${h(candidate.selfDeclaredOrganization)}</p>`:''}
  <div class="candidate-field"><span>本人の公約（収録した要約）</span>${promises.personal.length?`${promises.personal.slice(0,2).map(p=>`<p>${h(p.title||p.summary)}</p>${isPR&&p.electionId!==id?`<small>原資料：${h(catalog.elections.find(e=>e.id===p.electionId)?.district||'別の選挙資料')}</small>`:''}${link('/promise/'+p.id,'本人の公約を確かめる')}`).join('')}`:'<p>本人の公約本文は未収録です。</p>'}</div>
  ${promises.party.length?`<div class="candidate-field"><span>所属党の公約（同じ選挙・個人の公約とは別）</span><p>${h(promises.party[0].title)}</p>${link('/promises?owner=party&party='+encodeURIComponent(candidate.partyAtElection)+'&cycle='+election.electionNumber,'党の公約 '+promises.party.length+'件を見る')}</div>`:''}
  <div class="candidate-field"><span>確認できた活動・本人が公表した経歴</span><p>${h(activities[0]?.title||candidate.careerSummary||'経歴・活動の記録は未収録です。')}</p></div>
  <div class="card-footer"><label class="selection"><input type="checkbox" data-select-candidate="${h(candidate.id)}" data-election="${h(id)}" ${selected.some(item=>item.id===candidate.id)?'checked':''}><span>比較に入れる</span></label>${candidate.politicianId?link('/politician/'+candidate.politicianId,'議員の詳細'):''}</div>${sourceRef([...(candidate.sourceIds||[]),...(candidate.candidacySourceIds||[])],candidate.gazettePage?'公報 '+candidate.gazettePage+'ページ':'候補者名簿の根拠')}</article>`;
 }).join('')||empty('該当する候補者はありません','絞り込み条件を変えてください。')}</div>
 ${maxPage>1?`<div class="pagination">${page>1?link(routeURL('/election/'+id,{q:query,party:partyFilter,page:page-1}),'前へ','button compact','back'):''}<span>${page} / ${maxPage}ページ</span>${page<maxPage?link(routeURL('/election/'+id,{q:query,party:partyFilter,page:page+1}),'次へ','button compact'):''}</div>`:''}${sourceRef(election.sourceIds)}`;
}

function comparePage(id,params){
 const election=catalog.elections.find(item=>item.id===id);if(!election)return missing('選挙');
 const selected=selections(id);if(selected.length<2)return `${link('/election/'+id,'候補者一覧に戻る','back','back')}${heading('比べる候補者を選んでください')}${empty('２〜３人を選んで比較できます','同じテーマ・同じ項目で、公約と確認できた活動を並べます。',link('/election/'+id,'候補者を選ぶ','button primary'))}`;
 const theme=params.get('theme')||'all',themes=unique(selected.flatMap(candidate=>{const p=candidatePromises(catalog,candidate);return [...p.personal,...p.party].map(p=>p.theme);}));
 const cells=kind=>selected.map(candidate=>{
  const group=candidatePromises(catalog,candidate,theme),acts=catalog.activities.filter(item=>item.candidateId===candidate.id||candidate.politicianId&&item.politicianId===candidate.politicianId);
  let content='';
  const renderGroup=(promises,owner)=>promises.map(p=>`<div class="comparison-item"><span class="tag neutral">${h(owner)}</span>${kind==='progress'?tag(p.progress||'未評価',p.progressStage==='partially-implemented'?'amber':'neutral'):''}<p>${h(p.title||p.summary)}</p>${kind==='progress'?`<p class="quiet">${h(p.progressAsOf||'進捗の時点は未確認')}<br>${h(p.progressReason||'進捗を判断する資料は未収録です。')}</p>${p.progressScope?`<p class="quiet">${h(p.progressScope)}</p>`:''}`:p.summary&&p.summary!==p.title?`<p class="quiet">${h(p.summary)}</p>`:''}${sourceRef(kind==='progress'&&p.progressEvidenceVerified?p.progressSourceIds:p.sourceIds)}${link('/promise/'+p.id,'根拠を見る')}</div>`).join('');
  if(kind==='promise'||kind==='progress')content=(group.personal.length?renderGroup(group.personal,candidate.originalElectionId&&candidate.originalElectionId!==id?'本人の公約（小選挙区の原資料）':'本人の公約'):'<p class="quiet">この分野の本人の公約は未収録です。</p>')+renderGroup(group.party,'党の公約 · 本人の成果とは別');
  if(kind==='activity')content=acts.length?acts.map(a=>`<div class="comparison-item"><p>${h(a.title)}</p><p class="quiet">${h(a.date)} · ${h(a.role)}</p><p class="quiet">${h(a.relationToElectionPromise||'')}</p>${sourceRef(a.sourceIds)}</div>`).join(''):`<p>${h(candidate.careerSummary||'経歴・議会活動の資料は未収録です。')}</p><p class="quiet">活動や議員歴がないと判断したものではありません。</p>${sourceRef(candidate.sourceIds)}`;
  return `<article class="comparison-cell"><header>${h(candidate.name)}<div class="identity-tags">${party(candidate.partyAtElection)}</div></header>${content}</article>`;
 }).join('');
 return `${link('/election/'+id,'候補者を選び直す','back','back')}${heading('約束と活動を、比べる。',election.district||election.name,'本人の公約と党の公約を区別し、同じテーマで確認します。点数や投票先の推薦は付けません。')}
 <div class="pills" role="group" aria-label="比較する分野">${['all',...themes].map(value=>`<button type="button" class="pill" data-action="compare-theme" data-election="${h(id)}" data-theme="${h(value)}" aria-pressed="${theme===value}">${h(themeNames[value]||value)}</button>`).join('')}</div>
 <div class="comparison" data-count="${selected.length}" style="--columns:${selected.length}"><div class="comparison-people">${selected.map(candidate=>identity(candidate,{election:true})).join('')}</div>${notice('本人の公約・行動と、党の公約・制度の進捗は別に表示します。未収録や未評価を、活動なし・未達とは扱いません。')}
 ${[['promise','今回の公約'],['activity','確認できた過去の活動・経歴'],['progress','本人の行動・制度の進捗']].map(([key,label])=>`<section class="comparison-row"><h2>${h(label)}</h2><div class="comparison-grid">${cells(key)}</div></section>`).join('')}</div><div class="page-actions">${link('/election/'+id,'候補者の組み合わせを変える','button full','people')}</div>`;
}
function promisesPage(params){
 const theme=params.get('theme')||'all',owner=params.get('owner')||'all',status=params.get('status')||'all',partyFilter=params.get('party')||'all',cycle=params.get('cycle')||'all';
 const themes=unique(catalog.promises.map(p=>p.theme)),parties=unique(catalog.promises.filter(p=>p.ownerType==='party').map(p=>p.partyName)),cycles=unique(catalog.promises.map(p=>p.applicableElectionNumber||catalog.elections.find(e=>e.id===p.electionId)?.electionNumber)).sort();
 const promises=catalog.promises.filter(p=>(theme==='all'||p.theme===theme)&&(owner==='all'||(owner==='party'?p.ownerType==='party':p.ownerType!=='party'))&&(status==='all'||p.progressEvidenceVerified===true)&&(partyFilter==='all'||p.ownerType==='party'&&p.partyName===partyFilter)&&(cycle==='all'||String(p.applicableElectionNumber||catalog.elections.find(e=>e.id===p.electionId)?.electionNumber)===cycle));
 const maxPage=Math.max(1,Math.ceil(promises.length/pageSize)),page=Math.max(1,Math.min(maxPage,Math.floor(Number(params.get('page'))||1)));
 return `${heading('公約を確かめる','選挙時の約束と、その後','本人の公約と党の公約を分け、進捗は本人の行動、法案提出、制度の成立・施行・一部実施を区別します。')}
 <form class="filters promise-filters" data-form="promises-filter"><input type="hidden" name="theme" value="${h(theme)}"><label class="filter-field">公約の主体<select name="owner">${[['all','本人と党'],['personal','本人の公約'],['party','党の公約']].map(([v,t])=>`<option value="${v}" ${owner===v?'selected':''}>${t}</option>`).join('')}</select></label>
 <label class="filter-field">進捗の根拠<select name="status"><option value="all">すべて</option><option value="verified" ${status==='verified'?'selected':''}>確認できた記録</option></select></label>
 <label class="filter-field">党の公約を絞る<select name="party"><option value="all">すべての党</option>${parties.map(v=>`<option ${partyFilter===v?'selected':''}>${h(v)}</option>`).join('')}</select></label>
 <label class="filter-field">対象選挙<select name="cycle"><option value="all">すべて</option>${cycles.map(v=>`<option value="${h(v)}" ${cycle===String(v)?'selected':''}>第${h(v)}回衆院選</option>`).join('')}</select></label><button class="button primary" type="submit">絞り込む</button></form>
 <div class="pills" role="group" aria-label="公約の分野">${['all',...themes].map(value=>`<button class="pill" type="button" data-action="promise-theme" data-theme="${h(value)}" aria-pressed="${theme===value}">${h(themeNames[value]||value)}</button>`).join('')}</div>
 <div class="section-heading"><h2>公約 ${promises.length}件</h2><span>進捗根拠を照合 ${promises.filter(p=>p.progressEvidenceVerified).length}件</span></div>
 ${notice('確認できた記録には、要請・提案や現行水準の確認も含まれます。達成した件数ではありません。未評価は根拠未収録の意味です。')}
 <div class="stack">${promises.slice((page-1)*pageSize,page*pageSize).map(p=>promiseCard(p)).join('')||empty('該当する公約はありません','条件を変えてください。')}</div>
 <div class="pagination">${page>1?link(routeURL('/promises',{theme,owner,status,party:partyFilter,cycle,page:page-1}),'前へ','button compact','back'):''}<span>${page} / ${maxPage}ページ</span>${page<maxPage?link(routeURL('/promises',{theme,owner,status,party:partyFilter,cycle,page:page+1}),'次へ','button compact'):''}</div>`;
}
function promisePage(id){
 const promise=catalog.promises.find(item=>item.id===id);if(!promise)return missing('公約');
 const candidate=candidateByID(promise.candidateId),partyOwned=promise.ownerType==='party';
 return `${link('/promises','公約一覧に戻る','back','back')}${heading(promise.title||promise.summary,partyOwned?'党の公約 · '+promise.partyName:candidate?.name||'選挙公約')}
 ${partyOwned?party(promise.partyName):''}<div class="tag-row">${tag(promise.progress||'未評価','neutral')}${tag(themeNames[promise.theme]||promise.theme)}</div>
 <div class="card"><dl class="key-values"><div><dt>公約の主体</dt><dd>${h(partyOwned?promise.partyName+'（党の公約）':candidate?.name||'候補者本人')}<small>${h(partyOwned?'第'+promise.applicableElectionNumber+'回衆院選の政策。候補者個人の公約とは区別します。':'候補者本人が提出した公報などの記録です。')}</small></dd></div>
 <div><dt>公約の対象時点</dt><dd>${h(promise.asOf||'未確認')}${promise.asOfNote?`<small>${h(promise.asOfNote)}</small>`:''}</dd></div><div><dt>原文から確認した内容</dt><dd>${h(promise.summary||promise.title)}<small>原文の要約です。条件や対象を出典でも確認できます。</small></dd></div><div><dt>期限</dt><dd>${h(promise.deadline||'具体的な期限は未確認')}</dd></div>${promise.notes?`<div><dt>補足</dt><dd>${h(promise.notes)}</dd></div>`:''}</dl></div>
 <div class="section-heading"><h2>公約の原文</h2></div>${promise.sourceLocator?`<p class="quiet">${h(promise.sourceLocator)}</p>`:''}${sourcesHTML(promise.sourceIds)}
 <div class="section-heading"><h2>確認できた進捗</h2><span>${h(promise.progressAsOf||'根拠未収録')}${promise.progressAsOf?'時点':''}</span></div><div class="card"><h3>${h(promise.progress||'未評価')}</h3><p>${h(promise.progressReason||'進捗を確認する資料は未収録です。')}</p>
 ${promise.effectiveAt?`<p class="progress-date">${promise.implementationStarted?'対応部分の開始日':'施行・開始予定日'}：${h(promise.effectiveAt)}</p>`:''}${promise.progressScope?`<div class="promise-state"><strong>確認できた範囲と条件</strong><p>${h(promise.progressScope)}</p></div>`:''}
 ${promise.attributionNote?`<p class="quiet">${h(promise.attributionNote)}</p>`:''}${promise.progressReviewNote?`<p class="quiet">${h(promise.progressReviewNote)}</p>`:''}</div>${promise.progressHistory?.length?`<div class="section-heading"><h2>これまでの確認記録</h2></div><div class="card">${promise.progressHistory.map(item=>`<div class="audit-row"><strong>${h(item.asOf)}</strong><p>${h(item.progress)}</p>${sourceRef(item.sourceIds)}</div>`).join('')}</div>`:''}
 ${promise.progressEvidenceVerified?`<div class="section-heading"><h2>進捗を確認した一次資料</h2></div>${sourcesHTML(promise.progressSourceIds)}`:''}
 ${promise.electionId?link('/election/'+promise.electionId,'同じ選挙の候補者を見る','button','vote'):''}`;
}
function fundingPage(params){const region=params.get('region')||'all';const type=params.get('type')||'all';const query=params.get('q')||'';const records=filterSupport(catalog.support,{region,type,query});const types=unique(catalog.support.map(r=>r.supportType));return `${heading('お金の行き先を見る。','国内と海外の支援','発表額・供与限度額・予算額と、確認できた支払いを区別して表示します。')}<div class="pills" role="group" aria-label="支援先で絞り込む">${[['all','すべて'],['domestic','国内'],['overseas','海外']].map(([value,label])=>`<button class="pill" type="button" data-action="funding-region" data-region="${value}" aria-pressed="${region===value}">${label} ${catalog.support.filter(r=>value==='all'||r.region===value).length}</button>`).join('')}</div><form class="filters" data-form="funding-filter"><input type="hidden" name="region" value="${h(region)}"><label class="filter-field filter-search">支援先・目的で探す<input type="search" name="q" value="${h(query)}" placeholder="例：フィジー、給付金"></label><label class="filter-field">支援の種類<select name="type"><option value="all">すべて</option>${types.map(value=>`<option ${type===value?'selected':''}>${h(value)}</option>`).join('')}</select></label><button class="button primary" type="submit">絞り込む</button></form>${notice('未確認は０円ではありません。融資は返済を前提とし、支払先・期間・精度が違う金額は合算しません。')}<div class="section-heading"><h2>支援 ${records.length}件</h2><span>一次資料を確認した初期収録分</span></div>${records.length?`<div class="stack">${records.map(fundingCard).join('')}</div>`:empty('該当する支援はありません','検索条件を変えてください。未掲載の支援がないという意味ではありません。')}`;}
function fundingDetail(id){const record=catalog.support.find(item=>item.id===id);if(!record)return missing('支援');const reference=supportReference(record);const ratio=paymentRatio(record);const label=record.paymentLabel||'確認できた支払・実行額';const precision=typeof record.amountPrecision==='string'?record.amountPrecision:record.amountPrecision?Object.values(record.amountPrecision).map(value=>typeof value==='string'?value:value?.rounding).filter(Boolean).join(' ／ '):'原資料の表示単位をご確認ください。';const roles=record.politicianRoles||[];const details=[['発表日',record.announcedAt||record.announcementDate||'未確認'],['発表総額',record.announcedAmountJPY===null?'未確認':money(record.announcedAmountJPY)],['発表・契約の対象',record.announcedPeriod||'未確認'],['予算額',record.budgetAmountJPY!==null&&record.budgetAmountJPY!==undefined?amountText(record,'budgetAmountJPY'):'未収録'],['契約日',record.contractDate||'未確認'],['支払・実行の対象期間',record.paidPeriod||'未確認'],['金額の精度・計算方法',record.paidAmountMethod||precision]];if(record.settledProjectExpenditureJPY!==undefined)details.push(['事業全体の決算額',record.settledProjectExpenditureLabel||money(record.settledProjectExpenditureJPY)]);return `${link('/funding','支援の一覧に戻る','back','back')}<div class="tag-row">${tag(record.region==='domestic'?'国内':'海外')}${tag(record.supportType,'neutral')}${tag(record.repayment,'neutral')}${tag(record.status||'確認中')}</div>${heading(record.shortTitle||record.title,record.country||record.recipient,record.purpose||'')}<div class="card finance-card"><h2>公表された額と支払い</h2><div class="amount-grid">${amountHTML(record,reference.kind==='budget'?'budgetAmountJPY':'announcedAmountJPY',reference.label)}${amountHTML(record,'paidAmountJPY',label)}</div>${reference.kind==='budget'?notice('発表総額は未確認です。左の数字は、原資料で確認した予算額です。'):''}${record.paidAmountIsDerived?notice('支払額は公表された人数と単価からの計算値です。原資料に総額が直接記載されたものではありません。','warn'):''}${record.paidAmountIsApproximate?notice(precision):''}${ratio!==null?`<div class="payment-track" role="img" aria-label="供与限度額に対する実行額の比率${Math.round(ratio*10000)/100}%"><span style="width:${ratio*100}%"></span></div><p class="track-caption">同じ事業の限度額に対する実績額です。政治家の達成率ではありません。</p>`:''}<div class="money-scope">${notice(record.paidScope||'支払いの範囲は未確認です。')}</div><details class="details"><summary>予算・契約・金額の精度を見る</summary><dl class="key-values">${details.map(([key,value])=>`<div><dt>${h(key)}</dt><dd>${h(value)}</dd></div>`).join('')}</dl></details></div><div class="section-heading"><h2>どこまでの支払いを確認？</h2></div><div class="card"><dl class="key-values"><div><dt>日本側の実施機関</dt><dd>${h(record.payer||(record.implementingBodies||[]).join('・')||'未確認')}</dd></div><div><dt>支援先・借入人</dt><dd>${h(record.recipient)}</dd></div><div><dt>支払・実行の確認方法</dt><dd>${h(record.verificationStatus||record.status||'資料の記載を確認')}</dd></div><div><dt>確認できた時点</dt><dd>${h(record.paidAsOf||record.paidPeriod||'未確認')}</dd></div></dl><p class="quiet">個々の銀行振込明細を取得したという意味ではありません。最終受益者への支払いと区別しています。</p></div><div class="section-heading"><h2>政治家はどう関わった？</h2></div><div class="card">${roles.length?roles.map(role=>`<div class="role-entry"><strong>${h(role.name)}</strong><p>${h(role.role||role.description||'関わりは未確認')}</p><p class="quiet">${h(role.roleAtTime||'')} ${h(role.date||'')}</p>${sourceRef(role.sourceIds)}</div>`).join(''):`<p>${h(record.politicianRoleNote||'特定の政治家との関係を確認できた記録は未収録です。')}</p>`}<p class="quiet">政治家の発表・説明と、政府・実施機関の決定や執行は区別します。</p></div>${(record.comparisonNotes?.length||record.limitations?.length)?`<div class="section-heading"><h2>比較するときの注意点</h2></div><div class="card"><ul class="method-list">${[...(record.comparisonNotes||[]),...(record.limitations||[])].map(text=>`<li>${h(text)}</li>`).join('')}</ul></div>`:''}<div class="section-heading"><h2>出典と確認した内容</h2></div>${sourcesHTML(record.sourceIds)}${link('/funding','一覧に戻る','button full','back')}`;}
function sourceCard(source){const url=safeURL(source.url);return `<article class="card source-card"><div class="tag-row">${tag(source.publisher||'公表元')}${tag(catalog.meta.isDemo?'架空資料':'一次資料','neutral')}</div><h3>${h(source.title)}</h3><div class="source-meta"><span>資料の時点：${h(source.dataAsOf||source.asOf||source.documentPeriod||source.publishedAt||source.publishedDate||'公表日未確認')}</span><span>確認日：${h(source.checkedAt||catalog.meta.checkedAt)}</span></div>${source.summary||source.evidenceSummary||source.evidence?`<p>${h(source.summary||source.evidenceSummary||source.evidence)}</p>`:''}${source.locator?`<div class="source-locator">確認箇所：${h(source.locator)}</div>`:''}${url?`<a class="inline-link" href="${h(url)}" target="_blank" rel="noopener noreferrer">原資料を開く ${icon('external')}</a>`:'<p class="quiet">操作サンプル用の架空資料です。</p>'}</article>`;}
function sourcesHTML(ids){const sources=unique(ids||[]).map(sourceByID).filter(Boolean);return sources.length?`<div class="source-list">${sources.map(sourceCard).join('')}</div>`:empty('根拠資料は未収録です','確認できた資料から掲載します。');}
function sourcesPage(params){const query=(params.get('q')||'').toLocaleLowerCase('ja');const sources=catalog.sources.filter(source=>!query||`${source.title} ${source.publisher}`.toLocaleLowerCase('ja').includes(query));return `${heading('出典と更新履歴','情報を確かめる','数字や公約の原文、対象時点、判断の根拠へたどれます。')}<form class="search-form" data-form="sources-search"><label class="offscreen" for="sources-q">資料名・公表元で探す</label><input id="sources-q" type="search" name="q" value="${h(params.get('q')||'')}" placeholder="資料名・公表元で探す"><button class="button primary" type="submit">探す</button></form><div class="section-heading"><h2>根拠資料 ${sources.length}件</h2><button type="button" class="button compact" data-action="export">掲載データを書き出す</button></div><div class="source-list">${sources.map(sourceCard).join('')}</div><div class="section-heading"><h2>この版の更新記録</h2></div><div class="card">${(catalog.audit||[]).map(item=>`<div class="audit-row"><strong>${h(item.date)}</strong> ${h(item.title||item.change)}${item.detail?`<small>${h(item.detail)}</small>`:''}</div>`).join('')||'<p class="quiet">更新記録は未収録です。</p>'}</div>`;}
function methodologyPage(){return `${heading('掲載範囲と確認のルール','このアプリについて','誰を支持するかを決めるために、同じ基準で事実と出典を並べます。')}<div class="card"><h2>いま確認できる範囲</h2><dl class="key-values"><div><dt>議員名簿</dt><dd>${catalog.politicians.length}人<small>衆議院：${h(catalog.meta.houseAsOf||'未確認')} ／ 参議院：${h(catalog.meta.councilAsOf||'未確認')}</small></dd></div><div><dt>現在の所属政党</dt><dd>${catalog.politicians.filter(person=>person.currentParty).length}人を党の資料等で照合<small>未確認の人は、会派を別項目で表示しています。</small></dd></div><div><dt>選挙・公約</dt><dd>${catalog.elections.length}選挙・${catalog.candidates.length}候補者・${catalog.promises.length}公約<small>第51回衆院選の候補者名簿を掲載。小選挙区と比例で重複する人は同じ人物です。参議院選・地方選、本人公約の未確認部分は未収録です。</small></dd></div><div><dt>公約の確認状況</dt><dd>本人 ${catalog.promises.filter(p=>p.ownerType!=='party').length}件／党 ${catalog.promises.filter(p=>p.ownerType==='party').length}件<small>進捗の一次資料を照合した記録 ${catalog.promises.filter(p=>p.progressEvidenceVerified).length}件。達成件数ではありません。</small></dd></div><div><dt>国内・海外支援</dt><dd>${catalog.support.length}事業<small>確認できた事業の初期収録分です。全支援の総額ではありません。</small></dd></div><div><dt>この版の更新日</dt><dd>${h(catalog.meta.checkedAt)}<small>版の更新日と各資料の確認日は別です。議員所属・支援を全件再調査した日ではありません。</small></dd></div></dl></div><div class="section-heading"><h2>表示の基準</h2></div><div class="card"><ol class="method-list"><li>公的機関の原資料、本人提出の選挙公報、政党の公式名簿を出典として記録します。</li><li>現在の政党、国会の会派、立候補当時の政党は別に表示します。</li><li>公約の原文確認と、実施・本人の関与の確認は別の作業です。根拠が不足する進捗は未評価です。</li><li>発表額、予算額、契約額、貸付実績、最終受給者への給付額を混同しません。</li><li>未確認を０円や未達と扱いません。概数、切り捨て、公開数値からの計算を明示します。</li><li>同じ支援の再発表や増額前後を二重に合算しません。異なる事業を単純合算した政治家ランキングは作りません。</li><li>帰化歴は本人が公表した経歴だけを、出典付きで掲載する設計です。今回の実データでは収集していません。</li><li>党の色は画面内で識別するための独自配色です。党公式の色や、良し悪しの評価を意味しません。</li></ol></div><div class="section-heading"><h2>データの確認と修正</h2></div><div class="card"><p>調査結果をそのまま公開用データにせず、出典、金額の単位、対象期間、人物の関わりを確認してから取り込みます。</p><p class="lead">今回の調査では別担当が給付金の数値と候補者の公約を読み直し、要約の条件抜けを修正しました。確認できない内容は未確認として残しています。</p><ul class="method-list">${(catalog.meta.limitations||[]).map(text=>`<li>${h(text)}</li>`).join('')}</ul></div><div class="section-heading"><h2>この端末に保存する内容</h2></div><div class="card"><p>フォロー、候補者の比較選択、文字サイズ、データ表示の選択を、このブラウザーだけに保存します。</p><p class="quiet">外部への送信、アカウント連携、他の端末との同期は行っていません。</p><div class="page-actions"><button class="button" type="button" data-action="clear-preferences">保存した選択を消す</button><button class="button" type="button" data-action="export">掲載データを書き出す</button></div></div>`;}
function missing(label){return heading(label+'が見つかりません')+empty('このデータには収録されていません','操作サンプルと実データを切り替えた場合は、一覧から選び直してください。',link('/','ホームへ戻る','button primary'));}
function contentFor(current){const parts=current.path.split('/').filter(Boolean);const id=parts[1]?decodeURIComponent(parts[1]):'';if(current.path==='/')return homePage();if(current.path==='/politicians')return politiciansPage(current.params);if(current.path==='/following')return politiciansPage(current.params,true);if(parts[0]==='politician')return politicianPage(id);if(current.path==='/elections')return electionPageList(current.params);if(parts[0]==='election')return electionPage(id,current.params);if(parts[0]==='compare')return comparePage(id,current.params);if(current.path==='/promises')return promisesPage(current.params);if(parts[0]==='promise')return promisePage(id);if(current.path==='/funding')return fundingPage(current.params);if(parts[0]==='funding')return fundingDetail(id);if(current.path==='/sources')return sourcesPage(current.params);if(parts[0]==='source'){const source=sourceByID(id);return source?link('/sources','出典一覧に戻る','back','back')+sourceCard(source):missing('資料');}if(current.path==='/methodology')return methodologyPage();return missing('画面');}
function render({scroll=false}={}){if(!catalog)return;const current=route();document.documentElement.dataset.large=String(preferences.large);app.innerHTML=`<header class="app-header"><div class="header-inner"><a class="brand" href="#/"><span class="brand-mark">${icon('window')}</span><span>政治の見える窓<small>約束と実績を、根拠でたどる。</small></span></a><div class="header-tools"><label class="dataset-choice"><span>表示データ</span><select id="dataset-mode" aria-label="表示するデータ"><option value="verified" ${preferences.mode==='verified'?'selected':''}>一次資料の実データ</option><option value="demo" ${preferences.mode==='demo'?'selected':''}>架空の操作サンプル</option></select></label><button type="button" class="type-button" data-action="text-size" aria-pressed="${preferences.large}" aria-label="${preferences.large?'文字を標準に戻す':'文字を大きくする'}">Aa<small>文字</small></button></div></div></header><div class="context-banner ${catalog.meta.isDemo?'demo':''}">${catalog.meta.isDemo?'操作サンプル：人物・政党・国・金額・資料はすべて架空です。':`一次資料に基づく収録版 · 版の更新日 ${h(catalog.meta.checkedAt)}`}${link('/methodology','掲載範囲','','')}</div><div class="app-layout"><nav class="side-nav" aria-label="主なメニュー">${navItems.map(([path,glyph,label])=>`<a class="nav-link ${isActive(path,current.path)?'active':''}" href="#${path}" ${isActive(path,current.path)?'aria-current="page"':''}>${icon(glyph)}${h(label)}</a>`).join('')}<div class="side-note">わからないことも、<br>そのまま表示します。${link('/methodology','確認のルール','','')}</div></nav><main id="main-content" class="main">${contentFor(current)}</main></div><footer class="app-footer"><div>政治の見える窓 · 非公式の試験公開版<br>対象時点と確認できた範囲を各項目に表示しています。</div><div><a href="#/methodology">掲載範囲・確認基準</a><a href="#/sources">出典と更新履歴</a></div></footer><nav class="mobile-nav" aria-label="下部メニュー">${[['/','home','ホーム'],['/elections','vote','候補者'],['/funding','bank','お金'],['/following','bookmark','フォロー']].map(([path,glyph,label])=>`<a href="#${path}" class="${isActive(path,current.path)?'active':''}" ${isActive(path,current.path)?'aria-current="page"':''}>${icon(glyph)}${label}</a>`).join('')}</nav>`;const title=app.querySelector('main h1')?.textContent||'出典';document.title=title+'｜政治の見える窓';if(current.params.get('section'))requestAnimationFrame(()=>document.getElementById(current.params.get('section'))?.scrollIntoView({block:'start'}));else if(scroll)window.scrollTo({top:0,behavior:'instant'});}
async function load(){const token=++loadingToken;try{const response=await fetch(new URL(preferences.mode==='demo'?'./demo.json':'./catalog.json',import.meta.url),{cache:'no-store'});if(!response.ok)throw new Error('データを読み込めませんでした。');const result=await response.json();if(token!==loadingToken)return;if(!Array.isArray(result.politicians)||!Array.isArray(result.sources))throw new Error('データの形式を確認してください。');catalog=result;render({scroll:true});}catch(error){if(token!==loadingToken)return;app.innerHTML=`<main class="error-page"><span class="eyebrow">政治の見える窓</span><h1>読み込みを確認してください</h1><p>${h(error.message)}</p><button type="button" class="button primary" data-action="retry">もう一度読み込む</button></main>`;}}
app.addEventListener('submit',event=>{const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const fields=Object.fromEntries(new FormData(form));if(form.dataset.form==='home-search')location.hash=routeURL('/politicians',{q:fields.q});if(form.dataset.form==='people-filter')location.hash=routeURL(form.dataset.path,fields);if(form.dataset.form==='funding-filter')location.hash=routeURL('/funding',fields);if(form.dataset.form==='elections-filter')location.hash=routeURL('/elections',fields);if(form.dataset.form==='candidate-filter')location.hash=routeURL('/election/'+form.dataset.election,fields);if(form.dataset.form==='promises-filter')location.hash=routeURL('/promises',fields);if(form.dataset.form==='sources-search')location.hash=routeURL('/sources',{q:fields.q});});
app.addEventListener('change',event=>{if(event.target.id==='dataset-mode'){preferences.mode=event.target.value;save();location.hash='/';load();return;}const input=event.target.closest('[data-select-candidate]');if(input){const id=input.dataset.election;const selected=new Set(preferences.compare[id]||[]);if(input.checked&&selected.size>=3){input.checked=false;toast('比較できるのは３人までです。');return;}input.checked?selected.add(input.dataset.selectCandidate):selected.delete(input.dataset.selectCandidate);preferences.compare[id]=[...selected];save();render();const replacement=app.querySelector(`[data-select-candidate="${CSS.escape(input.dataset.selectCandidate)}"]`);replacement?.focus({preventScroll:true});}});
app.addEventListener('click',event=>{const button=event.target.closest('button[data-action]');if(!button)return;const action=button.dataset.action;if(action==='retry'){load();return;}if(action==='text-size'){preferences.large=!preferences.large;save();render();return;}if(action==='follow'){const followed=new Set(preferences.followed);followed.has(button.dataset.id)?followed.delete(button.dataset.id):followed.add(button.dataset.id);preferences.followed=[...followed];save();render();toast(followed.has(button.dataset.id)?'フォローに登録しました。':'フォローを解除しました。');return;}if(action==='compare-theme'){location.hash=routeURL('/compare/'+button.dataset.election,{theme:button.dataset.theme});return;}if(action==='promise-theme'){location.hash=routeURL('/promises',{...Object.fromEntries(route().params),page:'',theme:button.dataset.theme});return;}if(action==='funding-region'){const current=route();location.hash=routeURL('/funding',{...Object.fromEntries(current.params),region:button.dataset.region});return;}if(action==='export'){const file=new Blob([JSON.stringify(catalog,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(file);const anchor=document.createElement('a');anchor.href=url;anchor.download=`politics-window-${preferences.mode}-${catalog.meta.checkedAt}.json`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('出典を含む掲載データを書き出しました。');return;}if(action==='clear-preferences'){preferences={mode:preferences.mode,large:false,followed:[],compare:{}};save();render();toast('フォローと比較の選択を消しました。');}});
window.addEventListener('hashchange',()=>{document.getElementById('toast').classList.remove('visible');render({scroll:true});});
document.querySelector('.skip-link').addEventListener('click',event=>{event.preventDefault();const main=document.getElementById('main-content');if(main){main.setAttribute('tabindex','-1');main.focus();main.scrollIntoView({block:'start'});}});
window.addEventListener('storage',event=>{if(event.key==='politics-window-v1'){const previousMode=preferences.mode;preferences=readPreferences(localStorage);previousMode!==preferences.mode?load():render();}});
load();
